import{_ as l,a0 as o,w as p,s as d,I as t,x as i,a1 as e,A as a,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"關閉 WSL 中正在運行的 Linux 發行版 | LCTT x X-CMD","titleTemplate":false,"description":"關閉 WSL 中正在運行的 Linux 發行版 | LCTT (202401) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"關閉 WSL 中正在運行的 Linux 發行版 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"關閉 WSL 中正在運行的 Linux 發行版 | LCTT (202401) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202401/20240124 Shut Down WSL Running Linux Distributions","title":"關閉 WSL 中正在運行的 Linux 發行版","tag":"202401","desc":""},"relativePath":"202401/20240124 Shut Down WSL Running Linux Distributions.md","filePath":"[post].md"}'),r={name:"202401/20240124 Shut Down WSL Running Linux Distributions.md"};function h(g,s,b,k,x,L){const n=o("Link");return p(),d("div",null,[s[18]||(s[18]=t("h1",{id:"關閉-wsl-中正在運行的-linux-發行版",tabindex:"-1"},[i("關閉 WSL 中正在運行的 Linux 發行版 "),t("a",{class:"header-anchor",href:"#關閉-wsl-中正在運行的-linux-發行版","aria-label":"Permalink to “關閉 WSL 中正在運行的 Linux 發行版”"},"​")],-1)),s[19]||(s[19]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202401/31/111542n7hb9b97xd56dpth.jpg",alt:""})],-1)),s[20]||(s[20]=t("blockquote",null,[t("p",null,"以下是使用 WSL 關閉在 Windows 內運行的 Linux 系統的不同方法。")],-1)),s[21]||(s[21]=t("p",null,"你使用 WSL 在 Windows 內運行 Linux 嗎？你想知道如何關閉在 WSL 中運行的 Linux 發行版嗎？",-1)),t("p",null,[s[1]||(s[1]=i("你當然可以在 WSL 中運行的 Linux 系統中 ",-1)),e(n,{href:"https://linuxhandbook.com/linux-shutdown-command/"},{default:a(()=>[...s[0]||(s[0]=[i("執行 shutdown 命令",-1)])]),_:1}),s[2]||(s[2]=i("：",-1))]),s[22]||(s[22]=u(`<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo shutdown now</span></span></code></pre></div><p>你還可以使用 <code>wsl</code> 命令關閉 Linux 系統。如果你有多個發行版在 WSL 中運行，這是一種極好的方法。</p><h3 id="在-wsl-中使用-windows-終端關閉-linux-系統" tabindex="-1">在 WSL 中使用 Windows 終端關閉 Linux 系統 <a class="header-anchor" href="#在-wsl-中使用-windows-終端關閉-linux-系統" aria-label="Permalink to “在 WSL 中使用 Windows 終端關閉 Linux 系統”">​</a></h3><p>在這個方法中，我假設通常的 <code>shutdown</code> 命令在 WSL Linux 系統中不起作用。</p><p>首先，在 Windows 中打開一個終端。在這裏，我使用的是 Windows 11，並在 WSL 2 下安裝了 Ubuntu。</p><p><img src="https://itsfoss.com/content/images/2024/01/open-a-terminal-from-start-menu.png" alt="打開 Windows 終端"></p><blockquote><p>💡 你可以在標準的 Windows 終端上使用 <code>wsl</code> 命令。在運行的 Linux 發行版中也可以訪問該命令。這裏，命令的名稱是 <code>wsl.exe</code>。</p></blockquote><p>現在，你需要列出已安裝的發行版及其狀態。為此，請輸入</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl --list --verbose</span></span>
<span class="line"><span>或</span></span>
<span class="line"><span>wsl -l -v</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2024/01/list-installed-distributions-and-their-status.png" alt="列出已安裝的發行版"></p><p>在這裏，你可以看到，我已經安裝了一個 WSL Ubuntu，它目前正在運行。</p><h4 id="關閉所有正在運行的-linux-發行版" tabindex="-1">關閉所有正在運行的 Linux 發行版 <a class="header-anchor" href="#關閉所有正在運行的-linux-發行版" aria-label="Permalink to “關閉所有正在運行的 Linux 發行版”">​</a></h4><p>有時，你可能想一次性停止正在運行的 WSL 實例。</p><p>在 Powershell 或 Windows 終端中，使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl --shutdown</span></span></code></pre></div><p>這將關閉所有會話。</p><p>此外，你還可以<strong>在任何正在運行的 WSL Linux 發行版終端中執行相同的功能</strong>。在發行版中時，你只需要使用 <code>wsl.exe</code> 而不是 <code>wsl</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl.exe --shutdown</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2024/01/shutdown-all-wsl-distros-within-another-distro.gif" alt="關閉所有正在運行的 WSL 發行版"></p><p>運行此命令後，所有正在運行的 WSL 發行版都將終止。WSL 2 輕量級虛擬機也被終止。<strong>因此，如果你想重新啓動 WSL 2 虛擬機環境，它將很有用。</strong></p><h4 id="終止特定的-linux-發行版" tabindex="-1">終止特定的 Linux 發行版 <a class="header-anchor" href="#終止特定的-linux-發行版" aria-label="Permalink to “終止特定的 Linux 發行版”">​</a></h4><p>要終止特定正在運行的 WSL 發行版，請打開單獨的 Windows 終端並運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl --terminate &lt;發行版名稱&gt;</span></span></code></pre></div><p>此處，發行版名稱是你使用 <code>wsl -l -v</code> ⁣ 命令列出所有已安裝的 WSL 發行版時獲得的名稱。</p><p><img src="https://itsfoss.com/content/images/2024/01/list-the-distro-to-terminate-only-that-one.png" alt="列出 WSL 發行版"></p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl --terminate Ubuntu</span></span></code></pre></div><p>執行後，指定的 Linux 發行版將被終止。</p><p>如果你在另一個發行版中，請使用以下命令列出系統上安裝的所有 WSL 發行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl.exe -l -v</span></span></code></pre></div><p>現在，使用以下命令終止所需的發行版：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>wsl.exe --terminate &lt;發行版名稱&gt;</span></span></code></pre></div><p><img src="https://itsfoss.com/content/images/2024/01/shutdown-successfully-completed.png" alt="從另一個 WSL 發行版中關閉 WSL 發行版"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>有些人直接關閉正在運行的 Linux 應用，但我認為這不太優雅。</p><p>另外，就像 Linux 終端一樣，你可以使用：</p><ul><li><code>logout</code> 命令，用於關閉該發行版。</li><li><code>exit</code> 命令用於退出運行 Linux 發行版的終端。</li><li>或者，按 <code>CTRL+D</code> 執行與 <code>exit</code> 命令相同的操作。</li></ul><p>但關閉 Linux 系統的 WSL 方式還有一個額外的優勢，即可以針對多個 Linux 系統執行此操作。</p><p>我希望它對你有幫助。</p><p><em>（題圖：DA/615fd564-a02c-4340-9c8f-ebabcc7c0e0c）</em></p><hr>`,40)),t("p",null,[s[4]||(s[4]=i("via: ",-1)),e(n,{href:"https://itsfoss.com/shut-down-wsl-distros/"},{default:a(()=>[...s[3]||(s[3]=[i("https://itsfoss.com/shut-down-wsl-distros/",-1)])]),_:1})]),t("p",null,[s[9]||(s[9]=i("作者：",-1)),e(n,{href:"https://itsfoss.com/author/sreenath/"},{default:a(()=>[...s[5]||(s[5]=[i("Sreenath",-1)])]),_:1}),s[10]||(s[10]=i(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[6]||(s[6]=[i("lujun9972",-1)])]),_:1}),s[11]||(s[11]=i(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:a(()=>[...s[7]||(s[7]=[i("geekpi",-1)])]),_:1}),s[12]||(s[12]=i(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:a(()=>[...s[8]||(s[8]=[i("wxy",-1)])]),_:1})]),t("p",null,[s[15]||(s[15]=i("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[13]||(s[13]=[i("LCTT",-1)])]),_:1}),s[16]||(s[16]=i(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:a(()=>[...s[14]||(s[14]=[i("Linux中國",-1)])]),_:1}),s[17]||(s[17]=i(" 榮譽推出",-1))])])}const w=l(r,[["render",h]]);export{f as __pageData,w as default};
